-- Hestia · 05 · Server-side plumbing: private configuration, Claude connector tokens, Web Push subscriptions,
-- notifications (inbox + push), calls from the database to the Edge Functions, schedules.

-- ---------- Private configuration (server only) ----------
-- Keys: internal_secret (database -> functions), functions_url (written by the functions themselves on their first call),
-- vapid_public / vapid_private (Web Push, generated by the "notify" function), and optional fallbacks for the function
-- secrets (anthropic_api_key, google_calendar_id, google_service_account_json…). See docs/SETUP.md.
create table private.config (
  key text primary key,
  value text not null,
  updated_at timestamptz not null default now()
);
insert into private.config (key, value) values ('internal_secret', private.random_token()) on conflict do nothing;

-- Reminders already sent (so a schedule that fires twice sends once)
create table private.sent (
  key text primary key,
  at timestamptz not null default now()
);

-- ---------- Tokens for the Claude connector (MCP) ----------
create table private.mcp_tokens (
  id uuid primary key default gen_random_uuid(),
  member_id uuid not null references public.members (id) on delete cascade,
  token_sha256 text not null unique,
  label text,
  created_at timestamptz not null default now(),
  last_used_at timestamptz,
  revoked_at timestamptz
);

-- An adult creates a token for themselves; it is shown once, only its fingerprint is kept
create or replace function public.create_mcp_token(p_label text default null) returns text
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := private.current_member_id();
  tok text := 'hst_' || private.random_token();
begin
  if not private.is_adult() then raise exception 'adults only' using errcode = '42501'; end if;
  insert into private.mcp_tokens (member_id, token_sha256, label) values (me, private.sha256_hex(tok), p_label);
  return tok;
end $$;
create or replace function public.list_mcp_tokens()
returns table (id uuid, member_id uuid, label text, created_at timestamptz, last_used_at timestamptz)
language sql stable security definer set search_path = '' as $$
  select t.id, t.member_id, t.label, t.created_at, t.last_used_at
  from private.mcp_tokens t
  where t.revoked_at is null and private.is_adult()
  order by t.created_at desc
$$;
create or replace function public.revoke_mcp_token(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not private.is_adult() then raise exception 'adults only' using errcode = '42501'; end if;
  update private.mcp_tokens set revoked_at = now() where id = p_id;
end $$;
revoke execute on function public.create_mcp_token(text), public.list_mcp_tokens(), public.revoke_mcp_token(uuid) from public, anon;
grant execute on function public.create_mcp_token(text), public.list_mcp_tokens(), public.revoke_mcp_token(uuid) to authenticated;

-- ---------- Web Push subscriptions (one per installed app) ----------
create table public.push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  member_id uuid not null references public.members (id) on delete cascade,
  endpoint text not null unique,
  subscription jsonb not null,
  device text,
  created_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now()
);
alter table public.push_subscriptions enable row level security;
create policy family on public.push_subscriptions for all to authenticated
  using ((select private.is_family())) with check ((select private.is_family()));
revoke all on public.push_subscriptions from anon;
grant select, insert, update, delete on public.push_subscriptions to authenticated;

-- ---------- Notifications (the in-app inbox; each one is also pushed to the member's devices) ----------
create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  member_id uuid not null references public.members (id) on delete cascade, -- who receives it
  kind text not null,          -- approval_request | approval_decision | comment | task_assigned | reminder | digest
  title text not null,
  body text,
  url text,                    -- where it opens, inside the app ("#/event/<id>")
  data jsonb not null default '{}'::jsonb,
  action_token text not null default private.random_token(), -- lets the notification's buttons act without opening the app
  read_at timestamptz,
  pushed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index notifications_member on public.notifications (member_id, created_at desc);
create index notifications_updated_at on public.notifications (updated_at);
alter table public.notifications enable row level security;
create policy family on public.notifications for all to authenticated
  using ((select private.is_family())) with check ((select private.is_family()));
revoke all on public.notifications from anon;
grant select, insert, update, delete on public.notifications to authenticated;
create or replace function private.stamp() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  new.updated_at := clock_timestamp();
  return new;
end $$;
create trigger stamp before update on public.notifications for each row execute function private.stamp();

-- ---------- Database -> Edge Functions ----------
-- Asynchronous (pg_net), after the commit. Never fails the write that caused it: without pg_net or before the functions
-- are deployed, it simply does nothing.
create or replace function private.call_function(fn text, body jsonb default '{}'::jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare
  base text := (select value from private.config where key = 'functions_url');
  secret text := (select value from private.config where key = 'internal_secret');
begin
  if base is null or secret is null then return; end if;
  perform net.http_post(
    url := base || '/' || fn,
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-hestia-secret', secret),
    body := body,
    timeout_milliseconds := 30000);
exception when others then
  raise notice 'call_function(%): %', fn, sqlerrm;
end $$;

-- A new notification is pushed at once
create or replace function private.notification_created() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  perform private.call_function('notify', jsonb_build_object('task', 'push', 'notification_id', new.id));
  return null;
end $$;
create trigger z_push after insert on public.notifications
  for each row execute function private.notification_created();

-- ---------- Who gets told what ----------
create or replace function private.member_name(p uuid) returns text
language sql stable security definer set search_path = '' as $$
  select coalesce((select name from public.members where id = p), 'Quelqu''un')
$$;

create or replace function private.event_when(e public.events) returns text
language sql stable security definer set search_path = '' as $$
  select case when e.all_day then to_char(e.start_date, 'DD/MM')
    else to_char(e.starts_at at time zone private.tz(), 'DD/MM "à" HH24"h"MI') end
$$;

-- Approval flow: asked -> the approvers are told; decided -> the one who asked is told
create or replace function private.event_notify() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  who uuid;
  asker uuid := coalesce(new.created_by, new.updated_by);
begin
  if new.deleted_at is not null then return null; end if;
  if new.status = 'pending' and (tg_op = 'INSERT' or old.status <> 'pending') then
    foreach who in array new.approver_ids loop
      continue when who = new.updated_by;
      insert into public.notifications (member_id, kind, title, body, url, data)
      values (who, 'approval_request', 'Demande d''approbation',
        private.member_name(asker) || ' : ' || new.title || ' (' || private.event_when(new) || ')',
        '#/event/' || new.id, jsonb_build_object('event_id', new.id));
    end loop;
  elsif tg_op = 'UPDATE' and old.status = 'pending' and new.status in ('confirmed', 'declined')
        and asker is not null and asker is distinct from new.updated_by then
    insert into public.notifications (member_id, kind, title, body, url, data)
    values (asker, 'approval_decision',
      case new.status when 'confirmed' then 'Approuvé ✅' else 'Refusé ❌' end,
      new.title || ' (' || private.event_when(new) || ') · ' || private.member_name(new.updated_by)
        || coalesce(' : ' || nullif(new.approval_note, ''), ''),
      '#/event/' || new.id, jsonb_build_object('event_id', new.id));
  end if;
  return null;
end $$;
create trigger z_event_notify after insert or update on public.events
  for each row execute function private.event_notify();

-- A comment: the other adults involved in the event are told
create or replace function private.comment_notify() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  e public.events;
  who uuid;
begin
  if tg_op <> 'INSERT' or new.deleted_at is not null then return null; end if;
  select * into e from public.events where id = new.event_id;
  if not found then return null; end if;
  for who in
    select distinct m.id from public.members m
    where m.role = 'adult' and m.active and m.deleted_at is null
      and m.id is distinct from coalesce(new.author_id, new.updated_by)
      and (m.id = e.created_by or m.id = any (e.approver_ids) or m.id = any (e.participant_ids) or m.id = any (e.caregiver_ids))
  loop
    insert into public.notifications (member_id, kind, title, body, url, data)
    values (who, 'comment', 'Commentaire · ' || e.title,
      private.member_name(coalesce(new.author_id, new.updated_by)) || ' : ' || left(new.body, 200),
      '#/event/' || e.id, jsonb_build_object('event_id', e.id));
  end loop;
  return null;
end $$;
create trigger z_comment_notify after insert on public.event_comments
  for each row execute function private.comment_notify();

-- A one-off task given to someone else: they are told
create or replace function private.task_notify() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  who uuid;
begin
  if new.chore_id is not null or new.deleted_at is not null or new.status <> 'todo' then return null; end if;
  foreach who in array new.assignee_ids loop
    continue when who is not distinct from new.updated_by;
    insert into public.notifications (member_id, kind, title, body, url, data)
    values (who, 'task_assigned', 'Nouvelle tâche',
      private.member_name(new.updated_by) || ' : ' || new.title
        || case when new.due_date > private.today() then ' (pour le ' || to_char(new.due_date, 'DD/MM') || ')' else '' end,
      '#/chores', jsonb_build_object('occurrence_id', new.id));
  end loop;
  return null;
end $$;
create trigger z_task_notify after insert on public.chore_occurrences
  for each row execute function private.task_notify();

-- An event changed here: Google Calendar is told right away (the 10-minute schedule is the safety net)
create or replace function private.event_to_gcal() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.gcal_dirty and new.updated_via <> 'gcal' then
    perform private.call_function('gcal-sync', jsonb_build_object('push', new.id));
  end if;
  return null;
end $$;
create trigger z_event_to_gcal after insert or update on public.events
  for each row execute function private.event_to_gcal();

revoke execute on all functions in schema private from public, anon, authenticated;
-- The three access checks, and what column defaults need (notifications.action_token, chores.start_date)
grant execute on function private.is_family(), private.is_adult(), private.current_member_id(), private.random_token(), private.tz(), private.today() to authenticated;

-- ---------- Live updates ----------
do $$
declare
  t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['members', 'settings', 'events', 'event_comments', 'birthdays', 'countdowns', 'dishes', 'meal_plan',
      'shopping_lists', 'shopping_sections', 'shopping_items', 'chores', 'chore_occurrences', 'notifications'] loop
      execute format('alter publication supabase_realtime add table public.%I', t);
    end loop;
  end if;
end $$;

-- ---------- Schedules (pg_cron + pg_net; skipped where the extensions do not exist, e.g. a bare local Postgres) ----------
do $$
begin
  create extension if not exists pg_net with schema extensions;
exception when others then
  raise notice 'pg_net not available: %', sqlerrm;
end $$;
do $$
begin
  create extension if not exists pg_cron with schema pg_catalog;
exception when others then
  raise notice 'pg_cron not available: %', sqlerrm;
end $$;
do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then return; end if;
  -- Times are UTC. Chores: every night around 3 am in Montréal, plus at noon as a safety net.
  perform cron.schedule('hestia-chores', '5 8,17 * * *', 'select public.generate_chore_occurrences()');
  perform cron.schedule('hestia-gcal', '*/10 * * * *', $c$select private.call_function('gcal-sync', '{}'::jsonb)$c$);
  perform cron.schedule('hestia-reminders', '*/15 * * * *', $c$select private.call_function('notify', '{"task": "reminders"}'::jsonb)$c$);
  perform cron.schedule('hestia-cleanup', '30 9 * * *',
    $c$delete from private.sent where at < now() - interval '14 days';
       delete from public.notifications where created_at < now() - interval '90 days'$c$);
end $$;
